 void syncCatalog(){loadingCatalog=true;IO.submit(()->{Catalog c=Catalog.online();SwingUtilities.invokeLater(()->{if(lobby){catalog=c;game=new Battle(c,mode,42,List.of());}loadingCatalog=false;repaint();});});}
 void mouse(MouseEvent e){mouseX=(int)((e.getX()-ox)/scale);mouseY=(int)((e.getY()-oy)/scale);}
 boolean blocked(){return lobby||choice||reveal!=null||game.done||game.paused||!game.choices.isEmpty();}
 void begin(){game=new Battle(catalog,mode,System.nanoTime(),new ArrayList<>(picks));lobby=false;choice=false;reveal=null;repeatTime=0;benchPage=focusPage=0;fx.clear();}
 void endReveal(){reveal=null;revealTime=0;}
 void step(){long now=System.nanoTime();double dt=Math.min(.05,(now-last)/1e9);last=now;clock+=dt;repeatTime=Math.max(0,repeatTime-dt);
  if(reveal!=null){revealTime+=dt;if(revealTime>=6.5)endReveal();}
  if(!blocked()){for(int i=0;i<game.speed;i++){game.update(dt);if(game.done||!game.choices.isEmpty())break;}if(dragging==null)game.automation(dt);}
  while(!game.notices.isEmpty()&&reveal==null){Notice n=game.notices.removeFirst();if(n.first()){reveal=n;revealTime=0;}else{repeatTitle=n.title();repeatTime=2.5;}}
  for(Hit h:game.hits)fx.add(new Fx(h));game.hits.clear();for(Fx f:fx)f.age+=dt;fx.removeIf(f->f.age>.65);if(fx.size()>170)fx.subList(0,fx.size()-170).clear();repaint();
 }
 static Color col(String hex){try{return Color.decode(hex);}catch(Exception e){return VIOLET;}}
 static Color alpha(Color c,int a){return new Color(c.getRed(),c.getGreen(),c.getBlue(),Math.max(0,Math.min(255,a)));}
