 String fit(String s,int max,int size){g.setFont(BASE.deriveFont(Font.BOLD,(float)size));if(g.getFontMetrics().stringWidth(s)<=max)return s;while(s.length()>1&&g.getFontMetrics().stringWidth(s+"…")>max)s=s.substring(0,s.length()-1);return s+"…";}
