 BufferedImage photo(String url){if(url==null||url.isBlank())return null;BufferedImage b=images.get(url);if(b==null&&loading.add(url)&&loading.size()<350){IO.submit(()->{try{HttpRequest req=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(8)).build();HttpResponse<InputStream> res=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(4)).build().send(req,HttpResponse.BodyHandlers.ofInputStream());try(InputStream in=res.body()){if(res.statusCode()!=200)return;byte[] bytes=in.readNBytes(8_000_001);if(bytes.length>8_000_000)return;BufferedImage im=ImageIO.read(new ByteArrayInputStream(bytes));if(im!=null&&im.getWidth()<=5000&&im.getHeight()<=5000)images.put(url,im);}}catch(Exception ignored){}});}return b;}
 void cover(BufferedImage im,double x,double y,double w,double h){if(im==null)return;double k=Math.max(w/im.getWidth(),h/im.getHeight());int ww=(int)(im.getWidth()*k),hh=(int)(im.getHeight()*k);Shape old=g.getClip();g.clip(new Rectangle2D.Double(x,y,w,h));g.drawImage(im,(int)(x+(w-ww)/2),(int)(y+(h-hh)/2),ww,hh,null);g.setClip(old);}
