  for(int i=0;i<18;i++){Point p=slot(i);double x=p.x()-40,y=p.y()-40;Unit u=game.at(i);boolean open=game.open(i);rr(x,y,80,80,10,open?new GradientPaint((float)x,(float)y,new Color(30,63,65),(float)x,(float)(y+80),new Color(20,39,54)):new GradientPaint((float)x,(float)y,new Color(36,37,52),(float)x,(float)(y+80),new Color(20,23,35)),open?alpha(MINT,u==null?210:125):new Color(75,79,100),open?1.6f:1);
   if(!open){Shape old=g.getClip();g.clip(new RoundRectangle2D.Double(x+1,y+1,78,78,10,10));for(int k=-80;k<160;k+=12)line(x+k,y,x+k-80,y+80,alpha(MUTED,25),2);g.setClip(old);g.setColor(MUTED);g.setStroke(new BasicStroke(2));g.draw(new Arc2D.Double(p.x()-8,p.y()-17,16,18,0,180,Arc2D.OPEN));rr(p.x()-12,p.y()-8,24,18,5,new Color(74,77,98),MUTED,1);circ(p.x(),p.y()+1,2,TEXT);center("LOCKED",p.x(),p.y()+27,10,MUTED,true);}
   else if(u==null){center("+",p.x(),p.y()+2,30,MINT,true);center("OPEN",p.x(),p.y()+20,10,MINT,true);}
   else{portrait(u,p.x(),p.y()-8,23);if(u.id==game.selected)ring(p.x(),p.y()-8,28,GOLD,2);center(fit(u.name,74,11),p.x(),p.y()+28,11,TEXT,true);center(u.grouped()?"★".repeat(u.level):"Lv."+u.level,p.x(),p.y()-29,10,u.grouped()?GOLD:MINT,true);progress(p.x()-24,p.y()+34,48,3,1-u.cd/game.stats(u).interval(),MINT);}
   if(dragging!=null&&tile(mouseX,mouseY)==i)rr(x,y,80,80,10,null,open?GOLD:RED,3);
  }
  for(Enemy e:game.enemies){Point p=point(e.d);double r=e.boss?15:8;Color c=e.boss?GOLD:e.slow>0?MINT:RED;shine(p.x(),p.y(),r*2.5,c);Path2D poly=new Path2D.Double();for(int i=0;i<6;i++){double a=Math.PI*i/3,xx=p.x()+Math.cos(a)*r,yy=p.y()+Math.sin(a)*r;if(i==0)poly.moveTo(xx,yy);else poly.lineTo(xx,yy);}poly.closePath();g.setColor(new Color(41,24,55));g.fill(poly);g.setColor(c);g.setStroke(new BasicStroke(2));g.draw(poly);circ(p.x()-r*.28,p.y(),2,c);circ(p.x()+r*.28,p.y(),2,c);progress(p.x()-r,p.y()-r-8,r*2,4,e.hp/e.max,c);if(e.boss)center("BOSS",p.x(),p.y()+r+12,10,GOLD,true);}
  for(Fx f:fx){Hit h=f.hit;double a=Math.max(0,1-f.age/.65);Color c=col(h.color());if(f.age<.18){line(h.from().x(),h.from().y(),h.to().x(),h.to().y(),alpha(c,(int)(a*130)),8);line(h.from().x(),h.from().y(),h.to().x(),h.to().y(),alpha(TEXT,(int)(a*255)),2);shine(h.to().x(),h.to().y(),30,c);}if(h.radius()>0&&f.age<.4)ring(h.to().x(),h.to().y(),h.radius()*(.3+f.age*1.75),alpha(c,(int)(a*165)),2);if(f.age<.55)center((h.critical()?"CRIT ":"")+Math.round(h.damage()),h.to().x(),h.to().y()-14-f.age*45,h.critical()?17:12,alpha(h.critical()?GOLD:TEXT,(int)(a*255)),true);if(!h.skill().isBlank())center(h.skill(),h.from().x(),h.from().y()-40-f.age*18,12,alpha(VIOLET,(int)(a*255)),true);}
