 static void check(boolean ok,String m){if(!ok)throw new AssertionError(m);}
 static void selfTest(){Catalog c=Catalog.bundled();check(c.groups.size()==9,"catalog");Battle b=new Battle(c,Mode.NORMAL,123,List.of("davichi"));check(b.capacity()==8,"initial capacity");for(int i=0;i<18;i++)b.add("태연",null,1,i);check(b.deployed()==8,"cap");Unit u=b.units.get(0);check(!b.move(u,ORDER[8]),"locked");b.gold=5600;for(int i=0;i<5;i++)b.expand();check(b.capacity()==18&&b.gold==0,"expand");b.deployAll();check(b.deployed()==18,"deploy all");b=new Battle(c,Mode.NORMAL,123,List.of("davichi"));b.auto=true;b.autoKind=Cast.NORMAL;b.automation(.8);check(b.tickets==17&&b.units.size()==1,"auto");b.paused=true;b.automation(1);check(b.tickets==17,"pause");b.paused=false;Group d=b.groups.stream().filter(a->a.id().equals("davichi")).findFirst().orElseThrow();for(String n:d.members())b.add(n,null,1,-1);check(b.combine(d),"combine");Unit a=b.selected();Unit v=b.add(d.name(),d,1,-1);check(b.merge(a,v)&&a.level==2,"merge");b.skip();b.update(.1);check(b.wave==1&&!b.enemies.isEmpty(),"wave");check(c.wave(40,1).hp()>c.wave(30,1).hp(),"extended waves");System.out.println("GRD native: core checks passed");}
 static void preview(String path)throws Exception{NativeClient p=new NativeClient(Catalog.bundled(),false);p.setSize(W,H);p.lobby=false;p.game.focus=p.game.groups.stream().filter(a->a.id().equals("ive")).findFirst().orElse(p.game.focus);for(int i=0;i<12;i++)p.game.cast(Cast.NORMAL,false);p.game.skip();for(int i=0;i<180;i++)p.game.update(.04);p.game.selected=p.game.units.get(0).id;p.game.hits.stream().limit(12).forEach(h->p.fx.add(new Fx(h)));BufferedImage b=new BufferedImage(W,H,BufferedImage.TYPE_INT_RGB);Graphics2D gr=b.createGraphics();p.paint(gr);gr.dispose();ImageIO.write(b,"png",new File(path));System.out.println("Rendered "+path);}
 public static void main(String[] args)throws Exception{if(args.length>0&&args[0].equals("--self-test")){selfTest();return;}if(args.length>1&&args[0].equals("--preview")){preview(args[1]);return;}SwingUtilities.invokeLater(()->{NativeClient p=new NativeClient(Catalog.bundled(),true);JFrame f=new JFrame("GRD — NEON ENCORE");f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);f.setContentPane(p);f.pack();f.setMinimumSize(new Dimension(900,580));f.setLocationRelativeTo(null);f.setVisible(true);p.syncCatalog();});}
